def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Increment a numeric string by one
    def increment_str_number(x: str) -> str:
        num_int = int(x)
        num_int += 1
        return str(num_int)

    # Generate the palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # If num is all 9's, next palindrome is 10...01
    if set(s) == {'9'}:
        return num + 2  # e.g. 9 -> 11, 99->101, 999->1001 etc.

    # We'll try to build palindrome from left half and compare
    mid = length // 2
    odd = length % 2 == 1

    left = s[:mid + (1 if odd else 0)]
    palindrome = make_palindrome(left, odd)

    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise increment the left part and make palindrome again
    left_inc = increment_str_number(left)
    # If incrementing left changes length, e.g. 999 + 1 = 1000
    # then palindrome length also increases by 1 or 2
    if len(left_inc) > len(left):
        # For example, 999 -> 1000 means length increases by 1
        # New palindrome will be 10...01 with length+1 or length+2 
        # but to keep it simple, just build palindrome from left_inc
        return int(make_palindrome(left_inc, odd))
    else:
        return int(make_palindrome(left_inc, odd))

