def find_exponentio(base, exponent):
    if not isinstance(base, tuple) or not isinstance(exponent, tuple):
        raise TypeError("Both inputs must be tuples.")

    len_base = len(base)
    len_exp = len(exponent)

    if len_base == 1 and len_exp == 1:
        # Single elements: just exponentiate
        return (base[0] ** exponent[0],)
    elif len_base == 1 and len_exp > 1:
        # base scalar, exponent tuple
        return tuple(base[0] ** e for e in exponent)
    elif len_base > 1 and len_exp == 1:
        # base tuple, exponent scalar
        return tuple(b ** exponent[0] for b in base)
    else:
        # both tuples length > 1
        if len_base != len_exp:
            raise ValueError("If both tuples have length > 1, their lengths must be equal.")
        return tuple(b ** e for b, e in zip(base, exponent))

