def get_total_number_of_sequences(n: int, m: int) -> int:
    """
    Count the number of sequences of length n where each element is a positive integer 
    from 1 to m, and each next element is >= 2 * previous element.
    """
    # dp[i][x]: number of valid sequences of length i ending with element x
    dp = [ [0] * (m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1 can be any element from 1 to m
    for x in range(1, m+1):
        dp[1][x] = 1

    for i in range(2, n+1):
        # To optimize, we can accumulate sums from dp[i-1]
        # We'll use a prefix sums array for dp[i-1]
        prefix = [0] * (m+2)
        for x in range(1, m+1):
            prefix[x] = prefix[x-1] + dp[i-1][x]

        for x in range(1, m+1):
            # The previous element must be <= x // 2
            limit = x // 2
            if limit >= 1:
                dp[i][x] = prefix[limit]
            else:
                dp[i][x] = 0

    return sum(dp[n][1:])

