def find_Max(nums):
    if not nums:
        return None  # or raise an exception if empty input is invalid

    left, right = 0, len(nums) - 1

    # If the array is not rotated (the smallest element is at the beginning),
    # then the last element is the max.
    if nums[left] < nums[right]:
        return nums[right]

    # Binary search for the pivot point (max element)
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element,
        # max must be in [mid, right]
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # After the loop, left points to the smallest element.
    # The max is the element before left, taking care of wrap-around.
    return nums[left - 1]

