def dif_Square(n):
    # Check if n can be expressed as a^2 - b^2 with integers a > b > 0
    # Recall a^2 - b^2 = (a - b)(a + b)
    # We look for factors x = a - b and y = a + b such that:
    # n = x * y, with y > x > 0, and (x + y) even (since a = (x+y)/2, b = (y - x)/2)
    if n <= 0:
        return False
    for x in range(1, int(n**0.5) + 1):
        if n % x == 0:
            y = n // x
            if y > x and (x + y) % 2 == 0:
                # a = (x + y) // 2, b = (y - x) // 2
                a = (x + y) // 2
                b = (y - x) // 2
                if a > b > 0:
                    return True
    return False

