def str_to_tuple(s: str) -> tuple:
    """
    Convert a string representing grouped numbers into a tuple of integers.
    The input string is expected to use a uniform delimiter to separate groups of digits.
    For example:
    - "1,234,567" with delimiter ',' -> (1, 234, 567)
    - "1.234.567" with delimiter '.' -> (1, 234, 567)
    - "1234567" with no delimiter -> (1234567,)

    If the input is empty or contains no digits, returns an empty tuple.

    Assumes uniform delimiters; mixed delimiters like "1,234.567" are not supported.

    Parameters:
    s (str): The input string with grouped numbers.

    Returns:
    tuple: A tuple of integers parsed from the input string.
    """
    if not s:
        return ()

    # Detect delimiter by checking which non-digit character occurs in the string (if any)
    # We expect uniform delimiters, so if multiple different delimiters exist, we do not handle that.
    delimiters = set(ch for ch in s if not ch.isdigit())
    if len(delimiters) > 1:
        # More than one delimiter found - inconsistent according to spec
        raise ValueError("Input string contains mixed or inconsistent delimiters.")

    if len(delimiters) == 0:
        # No delimiter, entire string is one number
        try:
            return (int(s),)
        except ValueError:
            # no digits or invalid number
            return ()

    delimiter = delimiters.pop()

    # Split by delimiter and convert each part to int
    parts = s.split(delimiter)
    try:
        return tuple(int(part) for part in parts)
    except ValueError:
        # If any part is not a valid integer, return empty tuple or raise as appropriate
        return ()

