def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            # search inside lists/tuples for nested dictionaries
            def max_dict_depth_in_seq(seq):
                max_d = 0
                for item in seq:
                    if isinstance(item, dict):
                        depth = dict_depth(item)
                        if depth > max_d:
                            max_d = depth
                    elif isinstance(item, (list, tuple)):
                        d_inside = max_dict_depth_in_seq(item)
                        if d_inside > max_d:
                            max_d = d_inside
                return max_d
            depth = 1 + max_dict_depth_in_seq(v)
            if depth > max_depth:
                max_depth = depth
    return max_depth

