    def create_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    mid = length // 2

    # Get left half (including middle if odd)
    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    pal_candidate = create_palindrome(left, odd_length)
    pal_candidate_int = int(pal_candidate)

    # If palindrome candidate is strictly greater than n, return it
    if pal_candidate_int > n:
        return pal_candidate_int

    # Otherwise, increment the left half and mirror again
    # Increment left half as a number string
