def find_solution(a, b, n):
    """
    Find integers x, y such that a*x + b*y = n.
    If no solution exists, return None.
    If b=0 and a divides n, return x = n//a, y=0 with smallest nonnegative x.
    Otherwise, return any one solution (x, y).
    """
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
