        if n % a == 0:
            x = n // a
            if x < 0:
                # smallest nonnegative x doesn't exist if x<0, but problem says return x=n/a anyway
                # so just return x as is
                return None
            return (x, 0)
        else:
            return None

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None

    # scale the solution
    x0 *= n // gcd
    y0 *= n // gcd

    # adjust sign according to a and b sign
