def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    def is_all_nines(num_str):
        return all(ch == '9' for ch in num_str)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create a palindrome by mirroring left half to right half
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    # Split into left half and middle (if odd length)
    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Form palindrome from left half
    pal_candidate = int(make_palindrome(left, odd))

    if pal_candidate > n:
        return pal_candidate

    # Increment the left half (including middle if odd)
    # Convert left to int, add 1, then form palindrome again
    left_num = int(left)
    left_num += 1
    left_str = str(left_num)

    # If incrementing left changes length, e.g. 999 -> 1000, handle separately
    if len(left_str) > len(left):
        # This happens when increment causes carry that changes length
        # For example 999 -> 1000, palindrome would be 100...001
        # So return 10...01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')

    return int(make_palindrome(left_str, odd))

