def find_solution(a, b, n):
    """
    Find nonnegative integers x, y such that a*x + b*y = n.
    Return (x, y) if such solution exists, otherwise return "No solution".
    """
    # We'll try all possible x from 0 up to n//a (if a != 0)
    # and check if y = (n - a*x)/b is a nonnegative integer.
    # If a or b is zero, handle accordingly.

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    max_x = n // a if a > 0 else n // a if a < 0 else 0
    # Because a could be negative, we want to iterate over x in a range that makes sense:
    # However since we want x,y >= 0, then x>=0 anyway.
    # Also, with negative a, n - a*x could be larger than n.
    # So limit x from 0 to n//a if a > 0, or 0 to n//a if a<0 but we must be careful.
    # Let's just take x from 0 up to n (since x,y >= 0 and a,b >= 0 is not guaranteed)
    # But since x,y >=0, and a*x + b*y = n, x cannot be larger than n if a>0 (or 0 if a<0)
    # For negative a, since x,y >=0, a*x <=0, so if a<0, a*x + b*y <= b*y <= n
    # So if a<0 and x>0, a*x <0, so b*y must be > n to compensate, impossible for y>=0.
    # Therefore if a<0, x must be 0.
    # Similarly for b.

    # So handle sign cases:
    if a > 0 and b > 0:
        max_x = n // a
        for x in range(max_x + 1):
            remainder = n - a * x
            if remainder < 0:
                continue
            if remainder % b == 0:
                y = remainder // b
                if y >= 0:
                    return (x, y)
    elif a > 0 and b < 0:
        # For y>=0 and b<0, b*y <= 0, so a*x + b*y <= a*x <= n
        # So a*x must be <= n, x>=0
        max_x = n // a
        for x in range(max_x + 1):
            remainder = n - a * x
            # remainder = b*y
            # b<0, y>=0 => b*y <= 0
            # remainder should be divisible by b
            if remainder % b == 0:
                y = remainder // b
                if y >= 0:
                    return (x, y)
    elif a < 0 and b > 0:
        # a<0, x>=0, so a*x <= 0
        # b*y = n - a*x >= n
        # y = (n - a*x)/b >= n / b (since -a*x >= 0)
        # But y>=0
        # x must be 0 because if x>0, a*x <0, n - a*x > n, so y larger
        # just try x=0
        x = 0
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    elif a < 0 and b < 0:
        # Both negative, x,y>=0, a*x + b*y <= 0 <= n
        # So for n>0, no solution
        if n != 0:
            return "No solution"
        else:
            # n=0, x,y=0 works
            return (0, 0)
    else:
        # a or b zero cases handled above
        pass

    return "No solution"

