def get_noOfways(n: int) -> int:
    # Number of ways to tile 2 x n board with 2x1 dominoes.
    # Base cases:
    if n == 0:
        return 1  # One way to tile empty board
    if n == 1:
        return 1  # Only vertical placement possible

    dp = [0] * (n + 1)
