def parse_nested_parens(paren_string: str) -> str:
    # Split the input string by spaces to get groups of parentheses
    groups = paren_string.split()
    # For each group, calculate the maximum depth using reduce (no loops or recursion)
    from functools import reduce

    def max_depth(group):
        # reduce over characters, track (current_depth, max_depth)
        _, max_d = reduce(
            lambda acc, c: (
                acc[0] + (1 if c == '(' else -1 if c == ')' else 0),
                max(acc[1], acc[0] + (1 if c == '(' else 0))
            ),
            group,
            (0, 0)
        )
        return str(max_d)

    # Map max_depth over groups without loops (using map)
    depths = list(map(max_depth, groups))
    return ', '.join(depths)

